def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Track opponent defection history
    opp_def = 0
    opp_coop = 0
    for _, o in history:
        if o == 'D':
            opp_def += 1
        else:
            opp_coop += 1

    opp_rate = opp_def / n

    # Consecutive opponent defections at tail
    tail_def = 0
    for _, o in reversed(history):
        if o == 'D':
            tail_def += 1
        else:
            break

    # Consecutive mutual cooperation at tail
    tail_cc = 0
    for m, o in reversed(history):
        if m == 'C' and o == 'C':
            tail_cc += 1
        else:
            break

    last_me, last_opp = history[-1]
    remaining = 100 - n

    # Opponent just cooperated
    if last_opp == 'C':
        # If we defected last and they cooperated, don't keep exploiting a saint
        if last_me == 'D':
            # Against highly cooperative opponent, resume cooperation
            if opp_rate < 0.15 and remaining > 2:
                return 'C'
            # Opponent is somewhat defective: keep exploiting occasionally
            if opp_rate > 0.4 and remaining > 3:
                if rng.random() < 0.55:
                    return 'D'
            return 'C'

        # Endgame exploitation against very cooperative opponent
        if remaining <= 2 and opp_rate < 0.2:
            return 'D'

        # Mostly cooperate, with rare probing defect to gather info/points
        if tail_cc >= 3 and remaining > 5 and rng.random() < 0.06:
            return 'D'
        if opp_rate > 0.5 and remaining > 5 and rng.random() < 0.4:
            return 'D'
        return 'C'

    # Opponent just defected
    # If long tail of defections, keep defecting
    if tail_def >= 3:
        return 'D'

    # If opponent is mostly defective overall, defect
    if opp_rate > 0.4:
        return 'D'

    # Isolated defection against a mostly cooperative opponent: retaliate once with high probability
    if tail_def == 1 and opp_rate < 0.2:
        # Sometimes forgive to break accidental retaliation cycles
        if remaining > 8 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Moderate defection rate: retaliate but sometimes forgive
    if remaining > 5 and rng.random() < 0.2:
        return 'C'
    return 'D'
